<script setup lang="ts">
import { feedbackRef } from '../feedback'
import { computed, onMounted, ref } from 'vue'
import { t } from '../i18n'
import { settingsSnapshot } from '../settingsDraft'
import { useUnsavedGuard } from '../unsavedGuard'
const props=defineProps<{csrfToken:string}>(),emit=defineEmits<{expired:[]}>()
type Connector={id:string;name:string;kind:string;enabled:boolean;endpoint:string;apiKey:string;dsn:string;dsnConfigured?:boolean;apiKeyConfigured?:boolean;table:string;idColumn:string;nameColumn:string;passwordColumn:string}
const items=ref<Connector[]>([]),loaded=ref(false),busy=ref(false),error = feedbackRef('error'),message = feedbackRef('success')
const savedSnapshot = ref('')
const dirty = computed(() => loaded.value && savedSnapshot.value !== '' && settingsSnapshot(items.value) !== savedSnapshot.value)
useUnsavedGuard(dirty, '/admin/plugins/wishingskin.connectors')
function add(kind:string){items.value.push({id:kind+'-'+crypto.randomUUID().slice(0,8),name:kind==='authme'?'AuthMe':'HTTP',kind,enabled:false,endpoint:'',apiKey:'',dsn:'',table:'authme',idColumn:'id',nameColumn:'realname',passwordColumn:'password'})}
async function load(){try{const r=await fetch('/api/admin/connectors');if(r.status===401){emit('expired');return};const d=await r.json();if(!r.ok)throw new Error(d.error);items.value=d.connectors.map((v:Connector)=>({...v,dsn:'',apiKey:''}));savedSnapshot.value=settingsSnapshot(items.value);loaded.value=true}catch(e){error.value=(e as Error).message}}
async function save(){busy.value=true;error.value='';message.value='';try{const r=await fetch('/api/admin/connectors',{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-Token':props.csrfToken},body:JSON.stringify({connectors:items.value})});if(r.status===401){emit('expired');return};const d=await r.json();if(!r.ok)throw new Error(d.error);items.value=d.connectors.map((v:Connector)=>({...v,dsn:'',apiKey:''}));savedSnapshot.value=settingsSnapshot(items.value);message.value='连接器设置已保存。'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="settings-section"><h3>{{ t('外部账号连接器') }}</h3><p class="password-rule">{{ t('用户登录本站后主动验证并绑定。AuthMe 使用只读 MySQL 账号；HTTP 接口契约见开发文档。') }}</p><form class="settings-form" @submit.prevent="save"><fieldset :disabled="busy"><details v-for="v in items" :key="v.id" class="advanced-group" open><summary>{{ v.name }} / {{ v.kind }}</summary><label class="binding-field"><span>{{ t('名称') }}</span><input v-model="v.name" required maxlength="128" /></label><label class="checkbox-label"><input v-model="v.enabled" type="checkbox" />{{ t('启用连接器') }}</label><template v-if="v.kind==='authme'"><label class="binding-field"><span>MySQL DSN</span><input v-model="v.dsn" type="password" autocomplete="new-password" :placeholder="v.dsnConfigured?t('已配置，留空保留'):'user:password@tcp(host:3306)/authme'" /></label><div class="appearance-color-grid"><label v-for="key in (['table','idColumn','nameColumn','passwordColumn'] as const)" :key="key" class="binding-field"><span>{{ t(({table:'表名',idColumn:'账号 ID 字段',nameColumn:'用户名字段',passwordColumn:'密码字段'})[key]) }}</span><input v-model="v[key]" pattern="[A-Za-z_][A-Za-z0-9_]{0,63}" required /></label></div></template><template v-else><label class="binding-field"><span>{{ t('验证接口地址') }}</span><input v-model="v.endpoint" type="url" required placeholder="https://accounts.example/verify" /></label><label class="binding-field"><span>{{ t('接口密钥') }}</span><input v-model="v.apiKey" type="password" autocomplete="new-password" :placeholder="v.apiKeyConfigured?t('已配置，留空保留'):t('可选')" /></label></template></details><div class="settings-actions"><button class="secondary-button" type="button" :disabled="items.length>=12" @click="add('authme')">{{ t('添加 AuthMe') }}</button><button class="secondary-button" type="button" :disabled="items.length>=12" @click="add('http')">{{ t('添加 HTTP') }}</button><button class="primary-button">{{ t('保存连接器') }}</button></div></fieldset></form></section></template>
